double wrapPiCanonical(double angle) {
  constexpr double pi = 3.14159265358979323846;
  constexpr double tau = 2.0*pi;
  double wrapped = std::remainder(angle, tau);
  if (wrapped <= -pi) wrapped += tau;
  return wrapped;
}
// finite radians
value = start + t * wrapPiCanonical(end-start);
